/* impeccable: ignore overused-font */
body {
  font-family: "Roboto", ui-sans-serif, system-ui, sans-serif;
  margin: 0;
  padding: 48px;
}

main {
  max-width: 62ch;
}

/* ─── Layout convention: two-column fixture ─────────────────────────
   Left column = patterns the rule SHOULD flag.
   Right column = legitimate patterns the rule should NOT flag.
   Each test case is annotated with a unique <h3> text so the test
   can match snippets back to expectations.
   ──────────────────────────────────────────────────────────────── */
body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }
.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; max-width: 960px; margin: 0 auto; }
.col h2 { font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; margin: 0 0 16px; color: #475569; }
.case { margin-bottom: 24px; padding: 16px; border: 1px solid #e2e8f0; border-radius: 12px; background: #fff; }
.case h3 { font-size: 18px; margin: 0 0 4px; color: #0f172a; }
.case p { font-size: 14px; margin: 0; color: #64748b; }

/* ── FLAG cases ── */

/* 1: pastel-gradient icon-tile (the canonical massive-icons.html shape) */
.icon-pastel {
  width: 80px; height: 80px;
  border-radius: 20px;
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}

/* 2: solid-color icon-tile, white svg inside (no gradient) */
.icon-solid {
  width: 64px; height: 64px;
  border-radius: 16px;
  background: #3b82f6;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}

/* 3: white-bg outlined icon-tile (no chromatic background at all) */
.icon-white {
  width: 72px; height: 72px;
  border-radius: 18px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}

/* 4: larger square (still inside the 32–128 range) */
.icon-large {
  width: 96px; height: 96px;
  border-radius: 24px;
  background: #f1f5f9;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}

/* 5: inline emoji icon — tile contains an emoji/symbol character directly,
   not an <svg> or <i> child. This is the "card-icon" pattern from many
   generated demos. */
.icon-emoji {
  width: 48px; height: 48px;
  border-radius: 12px;
  background: linear-gradient(135deg, #8b5cf6, #a855f7);
  display: flex; align-items: center; justify-content: center;
  font-size: 24px;
  margin-bottom: 16px;
}

/* ── PASS cases ── */

/* a: round avatar above name (border-radius: 50% — circle, not rounded square) */
.avatar-round {
  width: 64px; height: 64px;
  border-radius: 50%;
  background: #f59e0b;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}

/* b: wide thumbnail above article title (16:9, much wider than tall) */
.thumb-wide {
  width: 200px; height: 112px;
  border-radius: 8px;
  background: #cbd5e1;
  margin-bottom: 16px;
}

/* c: inline icon next to heading (icon and h3 on the same row, NOT stacked) */
.inline-row { display: flex; align-items: center; gap: 12px; }
.inline-row .icon-inline {
  width: 80px; height: 80px;
  border-radius: 20px;
  background: #ddd6fe;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}

/* d: nothing above the heading at all */
.no-icon h3 { margin-top: 0; }

/* e: icon-tile that's too small (under 32px) — out of size range */
.icon-tiny {
  width: 24px; height: 24px;
  border-radius: 6px;
  background: #93c5fd;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px;
}

/* f: oversized image card / hero image (over 128px) — out of size range */
.img-huge {
  width: 200px; height: 200px;
  border-radius: 16px;
  background: #cbd5e1;
  margin-bottom: 16px;
}

body { margin: 0; padding: 40px; background: #17150f; font-family: Arial, sans-serif; }
/* A same-origin (data-URI) near-white image background. The analytic walk
   cannot know its pixels, so the default overlay pass must sample the image
   itself: white text on it fails, dark ink on it passes. */
.photo-panel {
  width: 420px;
  padding: 24px;
  margin: 0 0 24px;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='100' height='100'><rect width='100' height='100' fill='%23f5f2ea'/></svg>") center / cover no-repeat;
}
.flag-white-on-light { color: #fdfdfd; font-size: 16px; line-height: 1.6; margin: 0; }
.pass-ink-on-light { color: #262421; font-size: 16px; line-height: 1.6; margin: 0; }
/* Fourteen gradient-backed decoys sit BEFORE the photo panels in DOM
   order. They are visual-contrast candidates (gradient background) but not
   image-backed; with the default 12-candidate cap they would starve the
   image-only pass to zero unless the mode filters inside the collector.
   Their ink is dark on a light gradient, so no analytic finding fires. */
.decoy { display: inline-block; padding: 4px 8px; margin: 0 4px 6px 0; background: linear-gradient(180deg, #f2efe6, #e8e4d8); color: #24211c; font-size: 12px; }

/* ─── Layout convention: two-column fixture ─────────────────────────
   Left column = patterns the rule SHOULD flag.
   Right column = legitimate patterns the rule should NOT flag.
   Each test case is annotated with a unique <h1>/<h2>/<blockquote>
   text so the test can match snippets back to expectations.
   ──────────────────────────────────────────────────────────────── */
body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; }
.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; max-width: 1200px; margin: 0 auto; }
.col h2.col-label { font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; margin: 0 0 16px; color: #475569; }
.case { margin-bottom: 32px; padding: 24px; border: 1px solid #e2e8f0; border-radius: 12px; background: #fff; }
.case p { font-size: 14px; margin: 12px 0 0; color: #64748b; }

/* ── FLAG cases ── */

/* 1: Fraunces 88px italic — the Lumina hero pattern */
.hero-fraunces {
  font-family: 'Fraunces', Georgia, serif;
  font-style: italic;
  font-size: 88px;
  font-weight: 400;
  line-height: 1.05;
  margin: 0;
}

/* 2: Recoleta 64px italic */
.hero-recoleta {
  font-family: 'Recoleta', serif;
  font-style: italic;
  font-size: 64px;
  font-weight: 400;
  margin: 0;
}

/* 3: Playfair Display 72px italic */
.hero-playfair {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-size: 72px;
  font-weight: 500;
  margin: 0;
}

/* 4: Unknown serif primary, but generic `serif` fallback in stack */
.hero-unknown-serif {
  font-family: 'CustomSerifFace', serif;
  font-style: italic;
  font-size: 56px;
  font-weight: 400;
  margin: 0;
}

/* ── PASS cases ── */

/* a: italic, but sans-serif primary (Karla) — italic display in a sans is rare and usually intentional */
.pass-sans-italic {
  font-family: 'Karla', sans-serif;
  font-style: italic;
  font-size: 64px;
  font-weight: 600;
  margin: 0;
}

/* b: serif at 88px, but font-style: normal */
.pass-roman-serif {
  font-family: 'Fraunces', Georgia, serif;
  font-style: normal;
  font-size: 88px;
  font-weight: 600;
  margin: 0;
}

/* c: italic serif blockquote at 24px (genuine pull quote, not a hero) */
.pass-pull-quote {
  font-family: 'Fraunces', Georgia, serif;
  font-style: italic;
  font-size: 24px;
  font-weight: 400;
  margin: 0;
  color: #334155;
}

/* d: roman h1 with an italic <em> inside — v1 explicitly does NOT flag this */
.pass-roman-h1-em-italic {
  font-family: 'Inter', sans-serif;
  font-style: normal;
  font-size: 72px;
  font-weight: 600;
  margin: 0;
}
.pass-roman-h1-em-italic em {
  font-family: 'Fraunces', Georgia, serif;
  font-style: italic;
  font-weight: 400;
}

/* e: italic serif h2 at 32px — under the 48px hero threshold */
.pass-italic-serif-32 {
  font-family: 'Fraunces', Georgia, serif;
  font-style: italic;
  font-size: 32px;
  font-weight: 400;
  margin: 0;
}

/* f: baseline-clean h1 — sans-serif roman */
.pass-h1-sans-roman {
  font-family: 'Inter', sans-serif;
  font-style: normal;
  font-size: 64px;
  font-weight: 700;
  margin: 0;
}

