.demo h4 { font-weight: 600; font-size: 13px; margin: 0; }
.demo p { font-size: 12px; color: #6b7280; margin: 4px 0 0; }

/* ── FLAG: bounce / elastic easing ── */
@keyframes bounce-keyframe {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
.bounce-animation { animation: bounce-keyframe 1s infinite; }
.elastic-transition { transition: transform 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55); }

/* ── FLAG: layout property transitions ── */
.width-transition { transition: width 0.3s ease; }
.height-transition { transition: height 0.4s ease-out; }
.padding-transition { transition: padding 0.2s linear; }
.margin-transition { transition: margin 0.3s ease-in; }
.max-height-transition { transition: max-height 0.5s ease; }
.multi-layout-transition { transition: width 0.3s ease, height 0.3s ease; }
.mixed-transition { transition: width 0.3s ease, opacity 0.3s ease; }
.transition-property-width { transition-property: width; transition-duration: 0.3s; }

/* ── PASS: good easing ── */
@keyframes fade-in-keyframe {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in-good { animation: fade-in-keyframe 0.4s cubic-bezier(0.16, 1, 0.3, 1); }
.ease-out-quart { transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1); }
.ease-out-expo { transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1); }

/* ── PASS: safe transitions ── */
.transform-transition { transition: transform 0.3s ease-out; }
.opacity-transition { transition: opacity 0.2s ease; }
.color-transition { transition: color 0.15s ease, background-color 0.15s ease; }
.shadow-transition { transition: box-shadow 0.2s ease; }
.all-transition { transition: all 0.3s ease; }
.multi-safe-transition { transition: transform 0.3s ease, opacity 0.3s ease, box-shadow 0.2s ease; }

    /* Two-column fixture: left col = should-flag, right col = should-pass.
       Regression for issue #359: `border-left: 4px solid purple` in a .html
       file never fired side-tab because the static cascade's shorthand color
       extraction only recognized 9 named colors — every other spec name
       (purple, rebeccapurple, crimson, teal, ...) was dropped from the
       shorthand, leaving the side at the default black, which reads as
       neutral and silently skips the check. The same declaration in a .css
       file was flagged by the regex engine, so the two engines disagreed. */

    :root {
      --accent: orange; /* named color behind a var() — must resolve and flag */
    }

    body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #fafafa; }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; max-width: 1120px; margin: 0 auto; }
    .col h2 { font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; margin: 0 0 16px; color: #475569; }
    .case { padding: 12px 16px; margin-bottom: 16px; }
    .case h3 { font-size: 14px; margin: 0 0 4px; }
    .case p { font-size: 13px; margin: 0; color: #64748b; }

    /* ── FLAG cases: colored side-tab borders using CSS named colors ── */

    /* 1: the exact reproducer from issue #359 — named purple in a <style>
          rule with background + padding + radius */
    #flag-named-purple {
      width: 400px;
      background: #f6f6f6;
      padding: 16px;
      border-left: 4px solid purple;
      border-radius: 8px;
    }

    /* 2: rebeccapurple — a longer name that contains another color name
          ("purple") as a substring; must match whole-token. Width 5px so the
          finding snippet is unique to this case. */
    #flag-named-rebecca {
      width: 400px;
      background: #ffffff;
      border-radius: 4px;
      border-left: 5px solid rebeccapurple;
    }

    /* 3: horizontal stripe variant — named crimson riding the top edge */
    #flag-named-crimson-top {
      width: 400px;
      background: #ffffff;
      border-top: 4px solid crimson;
    }

    /* 4: named teal, 3px, no radius — the bare w >= 3 arm */
    #flag-named-teal {
      width: 400px;
      background: #ffffff;
      border-left: 3px solid teal;
    }

    /* 5: named color behind a var() in the shorthand. Width 6px so the
          finding snippet is unique to this case. */
    #flag-named-var {
      width: 400px;
      background: #ffffff;
      border-radius: 4px;
      border-left: 6px solid var(--accent);
    }

    /* ── PASS cases: neutral named colors and non-side-tab shapes ── */

    /* 1: dimgray — chromatic-looking name, neutral value; must NOT fire */
    #pass-named-dimgray {
      width: 400px;
      background: #ffffff;
      border-radius: 4px;
      border-left: 4px solid dimgray;
    }

    /* 2: gainsboro — light neutral named color */
    #pass-named-gainsboro {
      width: 400px;
      background: #ffffff;
      border-radius: 4px;
      border-left: 3px solid gainsboro;
    }

    /* 3: named black side border — neutral, not a colored stripe */
    #pass-named-black {
      width: 400px;
      background: #ffffff;
      border-radius: 4px;
      border-left: 4px solid black;
    }

    /* 4: 1px named purple — too thin to qualify */
    #pass-named-thin {
      width: 400px;
      background: #ffffff;
      border-radius: 4px;
      border-left: 1px solid purple;
    }

    /* 5: uniform named purple border on all four sides — not a side-tab */
    #pass-named-allsides {
      width: 400px;
      background: #ffffff;
      border: 3px solid purple;
      border-radius: 4px;
    }

