    /* ============================================
       1. TRANSFORM ANCESTOR
       position:absolute overlays on body use document coords,
       but getBoundingClientRect is viewport-relative.
       Transforms on ancestors create new stacking contexts.
       ============================================ */
    .transform-container {
      transform: translateY(0);
      padding: 1rem;
      background: #f3f4f6;
      border-radius: 8px;
    }
    .transform-rotate {
      transform: rotate(0deg);
      padding: 1rem;
      background: #f3f4f6;
      border-radius: 8px;
    }
    .transform-scale {
      transform: scale(1);
      padding: 1rem;
      background: #f3f4f6;
      border-radius: 8px;
    }
    .transform-nested-outer {
      transform: translateX(0);
      padding: 1rem;
      background: #e5e7eb;
      border-radius: 8px;
    }
    .transform-nested-inner {
      transform: translateY(0);
      padding: 1rem;
      background: #d1d5db;
      border-radius: 8px;
    }

    /* ============================================
       2. CLOSED <details>
       Elements inside collapsed details may report
       a bounding rect but aren't visually present.
       ============================================ */
    details { margin-bottom: 1rem; }
    summary { cursor: pointer; font-weight: 600; }

    /* ============================================
       3. STICKY / FIXED POSITIONING
       Sticky elements change their containing block
       behavior during scroll.
       ============================================ */
    .sticky-container {
      height: 200px;
      overflow-y: auto;
      border: 1px solid #d1d5db;
      border-radius: 8px;
    }
    .sticky-header {
      position: sticky;
      top: 0;
      background: #1f2937;
      color: white;
      padding: 0.5rem 1rem;
      z-index: 10;
    }
    .sticky-content {
