:root {
  --ok: oklch(0.78 0.145 155);
  --line: rgba(0, 0, 0, 0.08);
}

/* FLAG: classic ::before accent stripe — absolute, full height, left edge,
   chromatic background resolved through a custom property. */
.card-stripe { position: relative; border-radius: 12px; }
.card-stripe::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 5px;
  background: var(--ok);
}

/* FLAG: right-edge variant using inset shorthand + literal color. */
.row-stripe { position: relative; }
.row-stripe::after {
  content: "";
  position: absolute;
  inset: 0 0 0 auto;
  width: 4px;
  background-color: #3b82f6;
}

/* PASS: 1px neutral hairline divider (below width threshold + neutral). */
.col + .col::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 1px;
  background: var(--line);
}

/* PASS: neutral 4px rail (timeline spine) — chromatic gate rejects it. */
.timeline::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 4px;
  background: rgb(210, 210, 214);
}

/* PASS: blockquote decoration is exempt in prose contexts. */
blockquote::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 4px;
  background: #d97706;
}

/* PASS: toggle knob — offset from the edge, not a stripe. */
.switch::before {
  content: "";
  position: absolute;
  left: 2px; top: 2px;
  width: 10px; height: 10px;
  border-radius: 50%;
  background: #3b82f6;
}

/* PASS: wide decorative panel, not a stripe. */
.panel::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 40px;
  background: #3b82f6;
}

/* PASS: horizontal underline accent (not full height, not edge-anchored
   vertically). */
.heading::after {
  content: "";
  position: absolute;
  left: 0; bottom: 0;
  width: 6px; height: 3px;
  background: #3b82f6;
}

:root { --dot: 8px; }

/* FLAG: tiny circular live dot on an infinite opacity pulse. */
.live-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #22c55e;
  animation: pulse 2.4s ease-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

/* FLAG: box-shadow ripple variant, var-sized, pill radius. */
.status .dot {
  width: var(--dot); height: var(--dot);
  border-radius: 999px;
  background: #ef4444;
  animation: ripple 1.8s linear infinite;
}
@keyframes ripple {
  0%   { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4); }
  100% { box-shadow: 0 0 0 6px rgba(239, 68, 68, 0); }
}

/* FLAG: longhand animation-name + iteration-count. */
.beacon {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: #f59e0b;
  animation-name: pulse;
  animation-duration: 2s;
  animation-iteration-count: infinite;
}

/* PASS: rotation-only spinner — same size class, must never flag. */
.spinner {
  width: 14px; height: 14px;
  border-radius: 50%;
  border: 2px solid #e5e7eb;
  border-top-color: #3b82f6;
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* PASS: named pulse but the local keyframes only rotate. */
.fake-pulse {
  width: 8px; height: 8px;
  border-radius: 50%;
  animation: pulse-ring 1s linear infinite;
}
@keyframes pulse-ring { to { transform: rotate(180deg); } }

/* PASS: large breathing card — not a dot. */
.breathing-card {
  width: 240px; height: 120px;
  border-radius: 16px;
  animation: pulse 3s ease-in-out infinite;
}

/* PASS: finite attention pulse (no infinite). */
.nudge {
  width: 8px; height: 8px;
  border-radius: 50%;
  animation: pulse 0.6s ease-out 3;
}

/* PASS: square badge, not circular. */
.square-badge {
  width: 12px; height: 12px;
  border-radius: 2px;
  animation: pulse 2s infinite;
}

/* FLAG (error): header logo dot whose size and animation live in
   separate rule blocks, animation added inside a matching media query,
   with a reduced-motion reset that must not mask the default. */
.rec-mark {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: #dc2626;
}
@media (prefers-reduced-motion: no-preference) {
  .rec-mark { animation: pulse 2.4s ease-in-out infinite; }
}
@media (prefers-reduced-motion: reduce) {
  .rec-mark { animation: none; }
}

    /* Two-column fixture: left = should flag, right = should pass.
       Covers the typography-quality rules that need real browser layout
       (line-length, tight-leading, tiny-text, justified-text, all-caps-body,
       wide-tracking, skipped-heading). All are browser-only — see
       tests/detect-antipatterns-browser.test.mjs for assertions. */
    body { font-family: system-ui, sans-serif; background: #fafafa; padding: 24px; margin: 0; color: #0f172a; line-height: 1.6; }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; max-width: 1280px; margin: 0 auto; }
    .col h2 { font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; margin: 0 0 16px; color: #475569; }
    .col h3 { font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; margin: 24px 0 8px; color: #64748b; }
    .case { margin-bottom: 16px; padding: 16px; background: white; border: 1px solid #e2e8f0; border-radius: 8px; }
    .case-label { display: block; font-size: 12px; color: #64748b; margin-bottom: 6px; font-style: italic; }

    /* ── FLAG: typography quality issues ── */

    /* Line length: 12px body text fits >85 chars/line in a ~528px column.
       12px is not below the tiny-text 12px floor (rule fires at <12px). */
    .long-lines {
      font-size: 12px;
      line-height: 1.6;
    }

    /* Tight leading */
    .tight-leading {
      font-size: 16px;
      line-height: 1.0;
      max-width: 40em;
    }

    /* Tiny body text */
    .tiny-text {
      font-size: 10px;
      line-height: 1.6;
      max-width: 40em;
    }
    .tiny-text-11 {
      font-size: 11px;
      line-height: 1.6;
      max-width: 40em;
    }

    /* Justified text without hyphens */
    .justified-no-hyphens {
      text-align: justify;
      max-width: 30em;
      font-size: 16px;
      line-height: 1.6;
    }

    /* All-caps long body */
    .all-caps-body {
      text-transform: uppercase;
      font-size: 16px;
      max-width: 40em;
      line-height: 1.6;
    }

    /* Wide letter spacing on body */
    .wide-tracking-body {
      letter-spacing: 0.15em;
      font-size: 16px;
      max-width: 40em;
      line-height: 1.6;
    }

    /* ── PASS: comfortable typography ── */

    .good-measure {
      max-width: 65ch;
      font-size: 16px;
      line-height: 1.6;
    }

    .good-leading {
      font-size: 16px;
      line-height: 1.6;
      max-width: 40em;
    }

    .good-text-size {
      font-size: 16px;
      line-height: 1.6;
      max-width: 40em;
    }

    /* Justified text WITH hyphens — fine */
    .justified-with-hyphens {
      text-align: justify;
      hyphens: auto;
      -webkit-hyphens: auto;
      max-width: 30em;
      font-size: 16px;
      line-height: 1.6;
    }

    /* Short label in all-caps (passes — under 30 chars) */
    .label-caps {
      text-transform: uppercase;
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.1em;
      color: #475569;
    }

    /* Wide tracking on a short uppercase label (passes — both conditions excluded) */
    .label-tracking {
      letter-spacing: 0.15em;
      text-transform: uppercase;
      font-size: 12px;
      font-weight: 600;
      color: #475569;
    }

