    body { font-family: system-ui, sans-serif; background: #fafafa; padding: 24px; margin: 0; color: #1a1a1a; }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; max-width: 1200px; margin: 0 auto; }
    .col h2 { font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; margin: 0 0 16px; color: #475569; }
    .col h3 { font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; margin: 24px 0 8px; color: #64748b; }
    .card { padding: 14px 16px; border-radius: 10px; margin-bottom: 10px; }
    /* Styled button color cases (declared via stylesheet so jsdom resolves them
       reliably — inline color doesn't always win over user-agent rules in jsdom
       for <a> and <button>). */
    .styled-pill-low { background-color: rgb(31, 26, 21); color: rgb(91, 79, 68); display: inline-block; padding: 9px 18px; border-radius: 999px; font-weight: 500; font-size: 14px; text-decoration: none; }
    .low-contrast-button { background-color: rgb(55, 65, 81); color: rgb(108, 114, 128); display: inline-block; padding: 10px 20px; border-radius: 8px; border: 0; font-size: 14px; }
    .good-pill-high { background-color: rgb(20, 20, 25); color: rgb(245, 240, 232); display: inline-block; padding: 9px 18px; border-radius: 999px; font-weight: 500; font-size: 14px; text-decoration: none; }
    .inline-link-low { color: rgb(170, 170, 170); }
    /* Chip / badge cases: text-bearing spans painting their own background. */
    .chip-sev-low { display: inline-block; background-color: rgb(182, 50, 45); color: rgb(92, 84, 73); font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 2px; }
    .chip-ok-high { display: inline-block; background-color: rgb(20, 20, 25); color: rgb(245, 240, 232); font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 2px; }
    .chip-sub9-low { display: inline-block; background-color: rgb(182, 50, 45); color: rgb(150, 60, 55); font-size: 8px; padding: 1px 4px; }
    .panel-reset { background: rgb(28, 30, 38); color: rgb(230, 232, 237); padding: 12px; }
    .panel-reset code { background: rgb(246, 242, 244); border-radius: 3px; padding: 1px 4px; }
    .panel-reset pre code { background: none; }
    /* issue #409 Case A: gradient-clipped text. The gradient IS the glyph fill
       (text-fill-color: transparent), not a backdrop. The inherited `color`
       (#e8e6e3) is never painted, so measuring it against the element's own
       gradient stops (#6d8cff / #a78bfa) is a false positive. */
    .ox-grad-text { background: linear-gradient(135deg, #6d8cff 0%, #a78bfa 50%, #6d8cff 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: #e8e6e3; font-size: 40px; font-weight: 800; }
    /* issue #409 Case B: a 9%-alpha accent glow stop over a dark surface. The
       stop composites to ~#121f1f, not the full-opacity #34c0a8, so text stays
       high-contrast. The dark wrapper supplies the surface beneath the glow. */
    .ox-dark-wrap { background: #0f0f11; padding: 16px; }
    .ox-glow { background: linear-gradient(160deg, rgba(52,192,168,0.09) 0%, #141419 65%); padding: 20px; }
    .ox-glow p { color: #e8e6e3; font-size: 18px; }
    .ox-glow .muted { color: #8e8c89; font-size: 16px; }
    /* Gradient stop written as color-mix with a bright nested ingredient.
       The stop paints as a 16% wash of the light oklch color (composited
       over the dark wrap it is near-black); the nested oklch(90% ...) is an
       INGREDIENT, never painted. A parser that re-extracts nested tokens
       appends it as a phantom opaque light stop and the worst-case ratio
       then flags the light text at ~1:1 against a color nobody sees. */
    .mix-dark-wrap { background: #0f0f11; padding: 16px; }
    .mix-glow { background: linear-gradient(160deg, color-mix(in oklab, oklch(90% 0.02 95) 16%, transparent) 0%, #141419 65%); padding: 20px; }
    .mix-glow p { color: #ded9cf; font-size: 16px; }
    /* currentcolor surface: background-color paints with the element's own
       text color, which is itself a var() token here. jsdom hands both
       through verbatim, so the walk must resolve the token via the
       custom-prop map instead of abstaining on a knowable surface. */
    :root { --fixture-bone: #e8e2d6; }
    .currentcolor-surface { background-color: currentcolor; color: var(--fixture-bone); padding: 14px 16px; border-radius: 10px; margin-bottom: 10px; }
    .currentcolor-low-text { color: #cfc9bd; font-size: 14px; }
    .currentcolor-good-text { color: #3a352c; font-size: 14px; }
    /* Same shape but the token does not exist: the surface truly cannot be
       read, so the walk must abstain rather than guess. */
    .currentcolor-unknown { background-color: currentcolor; color: var(--fixture-undefined-token); padding: 14px 16px; border-radius: 10px; }
    .currentcolor-unknown p { color: #efe9dd; font-size: 14px; }

