    :root { --fixture-glow: oklch(0.78 0.14 155); }
    .glow-oklch { box-shadow: 0 0 18px oklch(0.72 0.15 195 / 0.5); }
    .glow-hex { box-shadow: 0 0 16px #3b82f6; }
